import{_ as o}from"./chunks/window_compare.BladcMsj.js";import{_ as a,o as i,c as r,ao as t}from"./chunks/framework.DjdkLwjY.js";const n="/AdriaArrayGeometryPicker.jl/previews/PR22/assets/panel_compare.CvqzN2KW.png",k=JSON.parse('{"title":"Comparing picks","description":"","frontmatter":{},"headers":[],"relativePath":"manual/compare.md","filePath":"manual/compare.md","lastUpdated":null}'),s={name:"manual/compare.md"};function p(l,e,c,d,h,m){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="Comparing-picks" tabindex="-1">Comparing picks <a class="header-anchor" href="#Comparing-picks" aria-label="Permalink to &quot;Comparing picks {#Comparing-picks}&quot;">​</a></h1><p>You can show the picks of other files next to your own, for example to compare the picks of several people for the same profile, or your picks of the Moho with your picks of a slab. Compared picks are drawn as dashed lines and cannot be edited.</p><p><img src="'+o+'" alt=""></p><h2 id="Showing-picks-of-another-file" tabindex="-1">Showing picks of another file <a class="header-anchor" href="#Showing-picks-of-another-file" aria-label="Permalink to &quot;Showing picks of another file {#Showing-picks-of-another-file}&quot;">​</a></h2><ol><li><p>Load the profile.</p></li><li><p>Choose <strong>Menu → Load Compare Picks</strong> and choose a pick file (<code>.aagpp</code>, <code>.csv</code> or <code>.jld2</code>).</p></li><li><p>Repeat for more files.</p></li></ol><p>Each file gets:</p><ul><li><p>a dashed line in its own colour in the profile axis,</p></li><li><p>an entry with the file name (and the user stored in the file) in the <strong>Compare picks</strong> panel, with a toggle that shows or hides this line,</p></li><li><p>an entry in the <strong>Compare picks</strong> legend below the plot.</p></li></ul><p><img src="'+n+'" alt=""></p><p>The <strong>Compare Picks</strong> toggle at the top of the window shows or hides all compared picks at once. A line is visible while both its own toggle and the <strong>Compare Picks</strong> toggle are on. Loading a file switches the <strong>Compare Picks</strong> toggle on.</p><p>A file that is already shown is not loaded a second time.</p><h2 id="Picks-of-another-profile" tabindex="-1">Picks of another profile <a class="header-anchor" href="#Picks-of-another-profile" aria-label="Permalink to &quot;Picks of another profile {#Picks-of-another-profile}&quot;">​</a></h2><p>Unlike <strong>Load Picks</strong>, <strong>Load Compare Picks</strong> also shows picks that were made on another profile, because they may still be useful (for example on a profile that runs close by). Their entry in the panel gets a <strong>red background</strong>, and a warning is logged in the REPL. Their coordinates are drawn as they are: the distance along <em>their</em> profile is drawn as the distance along the loaded profile.</p><h2 id="When-compared-picks-are-removed" tabindex="-1">When compared picks are removed <a class="header-anchor" href="#When-compared-picks-are-removed" aria-label="Permalink to &quot;When compared picks are removed {#When-compared-picks-are-removed}&quot;">​</a></h2><p>Compared picks belong to the loaded profile. They are removed when you load another profile. They are stored in a saved state (<strong>Menu → Save State</strong>) and restored with it.</p><h2 id="Making-compared-picks-editable" tabindex="-1">Making compared picks editable <a class="header-anchor" href="#Making-compared-picks-editable" aria-label="Permalink to &quot;Making compared picks editable {#Making-compared-picks-editable}&quot;">​</a></h2><p>Compared picks cannot be edited. To continue working on the picks of a file, load it with <strong>Menu → Load Picks</strong> instead. This replaces your current picks.</p>',16)])])}const u=a(s,[["render",p]]);export{k as __pageData,u as default};
